_cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>
#include <cfloat>

__global__ void sdpa_fp16_kernel(const __half* __restrict__ Q,
                                 const __half* __restrict__ K,
                                 const __half* __restrict__ V,
                                 __half* __restrict__ out,
                                 int B, int H, int S, int D, float scale) {
    int b   = blockIdx.x;          // batch
    int h   = blockIdx.y;          // head
    int i   = blockIdx.z;          // query position
    int tid = threadIdx.x;         // dimension iterator

    extern __shared__ float shared[];   // S floats for softmax scores
    float* scores = shared;            // alias

    // -------------------------------------------------
    // 1) Compute raw attention scores Q·Kᵀ (scaled)
    // -------------------------------------------------
    float max_score = -FLT_MAX;
    for (int j = 0; j < S; ++j) {
        float dot = 0.0f;
        for (int d = 0; d < D; ++d) {
            int q_idx = ((b * H + h) * S + i) * D + d;
            int k_idx = ((b * H + h) * S + j) * D + d;
            dot += __half2float(Q[q_idx]) * __half2float(K[k_idx]);
        }
        float s = dot * scale;
        scores[j] = s;
        if (s > max_score) max_score = s;
    }
    __syncthreads();

    // -------------------------------------------------
    // 2) Softmax: exponentiate, normalize
    // -------------------------------------------------
    float sum_exp = 0.0f;
    for (int j = 0; j < S; ++j) {
        float exp_val = expf(scores[j] - max_score);
        scores[j] = exp_val;      // reuse storage for exp(score)
        sum_exp += exp_val;
    }
    __syncthreads();

    for (int j = 0; j < S; ++j) {
        scores[j] = scores[j] / sum_exp;
    }
    __syncthreads();

    // -------------------------------------------------
    // 3) Weighted sum with V -> output vector
    // -------------------------------------------------
    for (int d = tid; d < D; d += blockDim.x) {
        float out_val = 0.0f;
        for (int j = 0; j < S; ++j) {
            int v_idx = ((b * H + h) * S + j) * D + d;
            out_val += scores[j] * __half2float(V[v_idx]);
        }
        int out_idx = ((b * H + h) * S + i) * D + d;
        out[out_idx] = __float2half(out_val);
    }
}

// ------------------------------------------------------------------
// Python‑visible entry point
// ------------------------------------------------------------------
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(),
                "All inputs must be CUDA tensors");
    TORCH_CHECK(Q.dtype() == torch::kHalf && K.dtype() == torch::kHalf && V.dtype() == torch::kHalf,
                "All inputs must be fp16");

    auto B = Q.size(0);
    auto H = Q.size(1);
    auto S = Q.size(2);
    auto D = Q.size(3);

    auto out = torch::empty_like(Q);

    const int threads = 256;                     // enough for D up to 1024
    dim3 grid(B, H, S);
    dim3 block(threads);
    float scale = 1.0f / sqrtf(static_cast<float>(D));
    size_t shared_mem = static_cast<size_t>(S) * sizeof(float);

    sdpa_fp16_kernel<<<grid, block, shared_mem>>>(
        reinterpret_cast<const __half*>(Q.data_ptr()),
        reinterpret_cast<const __half*>(K.data_ptr()),
        reinterpret_cast<const __half*>(V.data_ptr()),
        reinterpret_cast<__half*>(out.data_ptr()),
        B, H, S, D, scale);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }

    return out;
}
'''

# compile the extension
_sdpa_mod = load_inline(name='sdpa_cuda',
                        cpp_sources=_cpp_src,
                        cuda_sources=_cuda_src,
                        functions=['sdpa_forward'],
                        verbose=False)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return _sdpa_mod.sdpa_forward(Q, K, V)

